```json
{
  "hostname": "home-ai",
  "virtualization": {
    "type": "docker container",
    "host_kernel": "Linux 7.0.0-42-generic (Ubuntu SMP PREEMPT_DYNAMIC, x86_64)"
  },
  "cpu": {
    "model": "AMD Ryzen 7 5700X 8-Core Processor",
    "vendor": "AuthenticAMD",
    "architecture": "x86_64",
    "sockets": 1,
    "cores": 8,
